import{_ as i,o,c as a,a2 as t}from"./chunks/framework.BN2sqjC1.js";const p=JSON.parse('{"title":"Checklist manuale — condivisione, gruppi e configurazione (M4)","description":"","frontmatter":{},"headers":[],"relativePath":"qa/m4-sharing.md","filePath":"qa/m4-sharing.md"}'),n={name:"qa/m4-sharing.md"};function l(r,e,c,s,d,u){return o(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="checklist-manuale-—-condivisione-gruppi-e-configurazione-m4" tabindex="-1">Checklist manuale — condivisione, gruppi e configurazione (M4) <a class="header-anchor" href="#checklist-manuale-—-condivisione-gruppi-e-configurazione-m4" aria-label="Permalink to &quot;Checklist manuale — condivisione, gruppi e configurazione (M4)&quot;">​</a></h1><p>Da eseguire con due account (A proprietario, B destinatario) su due dispositivi o due istanze con directory dati distinte, contro <code>yarn dev:cloud:k3d</code>. Gli automatismi (<code>go test -tags integration</code>, vitest, Playwright) coprono i flussi sul mock e sul cloud reale; qui si verifica ciò che solo l&#39;app reale mostra.</p><p>Segnare <code>[x]</code> con data e sistema operativo.</p><h2 id="condivisione-di-una-cartella" tabindex="-1">Condivisione di una cartella <a class="header-anchor" href="#condivisione-di-una-cartella" aria-label="Permalink to &quot;Condivisione di una cartella&quot;">​</a></h2><ul><li>[ ] A collega un vault condiviso, tasto destro su una cartella → &quot;Condividi…&quot;: cerca B (e un gruppo di cui B è membro), livello Editor, &quot;Condividi&quot;.</li><li>[ ] B vede &quot;✉ 1 invito&quot; nel footer della barra destra (o nell&#39;intestazione a barra chiusa) e in Impostazioni → Condivisione: accetta; il mount compare in &quot;Condivisi con me&quot; e si apre con &quot;Apri&quot; (nome = nome dello share).</li><li>[ ] Il mount contiene solo la cartella condivisa, alla radice; B modifica una nota e ne crea un&#39;altra: A le riceve entro pochi secondi nella cartella originale.</li><li>[ ] Modifiche a righe diverse della stessa nota (A e B) si fondono; sulla stessa riga nasce una copia di conflitto. Un <code>.canvas</code> modificato da entrambi produce sempre una copia di conflitto.</li><li>[ ] A sposta un file fuori dalla cartella condivisa: sparisce dal mount di B (nel cestino); lo rimette dentro: ricompare.</li><li>[ ] A rinomina la cartella condivisa: B continua a sincronizzare senza interventi.</li></ul><h2 id="permessi" tabindex="-1">Permessi <a class="header-anchor" href="#permessi" aria-label="Permalink to &quot;Permessi&quot;">​</a></h2><ul><li>[ ] Con livello <strong>Viewer</strong>: nel blocco di stato del vault &quot;Lettore · sola lettura&quot;; l&#39;editor non accetta digitazione, Excalidraw e canvas sono in sola lettura, l&#39;explorer non offre nuovo/rinomina/elimina, le proprietà sono disabilitate.</li><li>[ ] A porta B da Viewer a Editor (e viceversa): il livello cambia nel mount aperto senza riavviare.</li><li>[ ] Un grant a un gruppo: un membro accetta per tutti; un altro membro vede il mount senza un secondo invito; &quot;Rifiuta&quot; da un invito di gruppo mostra l&#39;errore.</li><li>[ ] Documento singolo condiviso: B lo vede come mount con quel solo file; non può aggiungere altri file.</li><li>[ ] Vault privato (cifrato): &quot;Condividi…&quot; non compare; l&#39;API risponde <code>VAULT_ENCRYPTED</code>.</li></ul><h2 id="revoca-e-scadenza" tabindex="-1">Revoca e scadenza <a class="header-anchor" href="#revoca-e-scadenza" aria-label="Permalink to &quot;Revoca e scadenza&quot;">​</a></h2><ul><li>[ ] A revoca lo share: B vede &quot;Condivisione terminata&quot; e sceglie tra &quot;Conserva una copia&quot; (cartella in <code>&lt;dati&gt;/kept/</code>, apribile come vault) ed &quot;Elimina la copia&quot;.</li><li>[ ] Uno share con scadenza passata si comporta come revocato.</li><li>[ ] A rimuove B dai destinatari: stesso effetto per B.</li></ul><h2 id="configurazione-dell-amministratore" tabindex="-1">Configurazione dell&#39;amministratore <a class="header-anchor" href="#configurazione-dell-amministratore" aria-label="Permalink to &quot;Configurazione dell&#39;amministratore&quot;">​</a></h2><ul><li>[ ] Un profilo globale con <code>editor.fontSize</code> bloccato: nelle Impostazioni la voce è disabilitata, con &quot;Gestito dall&#39;amministratore&quot;, e mostra il valore del profilo.</li><li>[ ] Un valore non bloccato (es. <code>editor.lineWrap</code>) è un default: l&#39;utente lo cambia e la scelta resta dopo un riavvio.</li><li>[ ] <code>features.drawings=false</code>: spariscono &quot;Nuovo disegno&quot; e &quot;Inserisci disegno&quot;; <code>features.sharing=false</code> nasconde Condividi e gli inviti.</li><li>[ ] Offline (rete scollegata) la configurazione dell&#39;ultimo accesso resta in vigore.</li><li>[ ] <code>sync.interval_seconds</code> del profilo cambia l&#39;intervallo di polling.</li></ul><h2 id="web-ui-utente" tabindex="-1">Web UI utente <a class="header-anchor" href="#web-ui-utente" aria-label="Permalink to &quot;Web UI utente&quot;">​</a></h2><ul><li>[ ] <code>http://localhost:18081/</code> (stesso host dei redirect URI del realm): login Keycloak, Spazio utilizzato, I miei vault, Dispositivi, Condivisioni (accetta/rifiuta, revoca, gestione destinatari).</li><li>[ ] <code>/admin</code> non è visibile all&#39;utente normale; con ruolo <code>memobrain-admin</code> mostra il segnaposto.</li></ul>',13)])])}const v=i(n,[["render",l]]);export{p as __pageData,v as default};
